create table optimization_action_plan_snapshots(id uuid not null,tenant_id uuid not null,rules_version text not null check(rules_version='optimization-action-plan.v1'),source_routing_snapshot_id uuid not null,input_sha256 char(64) not null,status text not null check(status='completed'),source_finding_count integer not null check(source_finding_count>=0),source_cluster_count integer not null check(source_cluster_count>=0),package_count integer not null check(package_count between 0 and 5),packages jsonb not null check(jsonb_typeof(packages)='array'),execution_order jsonb not null check(jsonb_typeof(execution_order)='array'),created_at timestamptz not null,primary key(tenant_id,id),unique(tenant_id,input_sha256),foreign key(tenant_id,source_routing_snapshot_id) references evidence_gap_routing_snapshots(tenant_id,id));
create trigger optimization_action_plan_snapshots_append_only before update or delete on optimization_action_plan_snapshots for each row execute function reject_immutable_mutation();create trigger optimization_action_plan_snapshots_no_truncate before truncate on optimization_action_plan_snapshots for each statement execute function reject_immutable_mutation();alter table optimization_action_plan_snapshots enable row level security;alter table optimization_action_plan_snapshots force row level security;create policy optimization_action_plan_snapshots_tenant_isolation on optimization_action_plan_snapshots using(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid) with check(tenant_id=nullif(current_setting('app.tenant_id',true),'')::uuid);
